// HMAC-SHA256 over the canonical (compact) JSON serialisation of
// the payload. The receiving Express webhooks read the raw body and
// compute the HMAC themselves — replaying with the SAME canonical
// bytes is the only way the signature gate will pass.
//
// The original webhook fired by NymCard / MoneyHash / the biller rail
// was signed by THEIR secret; we cannot reproduce that. The receiving
// FlexPay webhook endpoints accept a replay-mode signature signed by
// the REPROCESSOR'S key under env.WEBHOOK_REPLAY_SECRET (see
// src/webhooks/*.webhook.ts → verifySignature). Either-or check:
// upstream provider signature OR the reprocessor's signature is
// honoured, never both.
const crypto = require('crypto');
const item = items[0].json;

const payload = item.payload;
if (!payload) throw new Error('REPROCESSOR_PAYLOAD_MISSING');

// Canonical JSON. JSON.stringify with no spacing matches what the
// backend's HMAC computation sees on the wire.
const body = JSON.stringify(payload);

const secret = $env.WEBHOOK_REPLAY_SECRET;
if (!secret) throw new Error('WEBHOOK_REPLAY_SECRET_NOT_SET');

const signature = crypto
  .createHmac('sha256', secret)
  .update(body, 'utf8')
  .digest('hex');

return [{
  json: {
    ...item,
    body,
    signature,
    // Header name the FlexPay webhook handlers look at first when
    // running in replay mode. The signing key is rotated
    // independently of partner secrets.
    signatureHeader: 'x-flexpay-replay-signature',
  },
}];

// State-machine reducer — applied to every replay outcome.
//
// Inputs (the upstream Replay POST result + the row from the cron
// query):
//   statusCode             HTTP code from the FlexPay endpoint
//   attempt_count          attempts so far (0 == first failure)
//   first_failed_at        ISO timestamp of the first failure
//   idempotency_key        unchanged across retries
//
// Outputs:
//   nextStatus       PENDING_RETRY | RESOLVED | DLQ_TERMINAL
//   nextAttemptAt    ISO timestamp the cron should consider this row
//                    again. For RESOLVED / DLQ_TERMINAL this is null.
//   nextAttemptCount monotonically incremented; capped at 8.
//
// Exponential backoff with jitter (Bible §3.5 retry curve):
//   attempt 1  →  1 min
//   attempt 2  →  2 min
//   attempt 3  →  4 min
//   attempt 4  →  8 min
//   attempt 5  →  16 min
//   attempt 6  →  32 min
//   attempt 7  →  64 min
//   attempt 8  →  128 min  (terminal if it fails)
// 25% multiplicative jitter to spread thundering herds.
//
// 2xx  → RESOLVED, no further retries.
// 4xx (non-401)  → DLQ_TERMINAL immediately. 4xx is a contract
//   violation, not a transient error; retrying will not change the
//   outcome and pages the on-call.
// 401 (signature)  → DLQ_TERMINAL with a distinguishing reason —
//   means the WEBHOOK_REPLAY_SECRET is mis-set on one side. Human
//   intervention required; do not retry blindly.
// 5xx / network  → PENDING_RETRY, schedule next attempt.
const replay = items[0].json;
const statusCode = replay.statusCode;
const attemptCount = (replay.attempt_count ?? 0) + 1;

const BASE_MS = 60 * 1000;
const CAP_ATTEMPTS = 8;

function backoff(n) {
  const exp = Math.min(n, CAP_ATTEMPTS);
  const window = BASE_MS * Math.pow(2, Math.max(0, exp - 1));
  const jitter = 1 + (Math.random() * 0.25 - 0.125);
  return Math.round(window * jitter);
}

let nextStatus;
let nextAttemptAt = null;
let dlqReason = null;

if (statusCode >= 200 && statusCode < 300) {
  nextStatus = 'RESOLVED';
} else if (statusCode === 401) {
  nextStatus = 'DLQ_TERMINAL';
  dlqReason = 'replay_signature_rejected';
} else if (statusCode >= 400 && statusCode < 500) {
  // 4xx that isn't a signature issue means the backend has rejected
  // the payload semantically. Replays will keep rejecting. Page now.
  nextStatus = 'DLQ_TERMINAL';
  dlqReason = `backend_${statusCode}`;
} else if (attemptCount >= CAP_ATTEMPTS) {
  // Retry budget exhausted.
  nextStatus = 'DLQ_TERMINAL';
  dlqReason = 'retry_budget_exhausted';
} else {
  nextStatus = 'PENDING_RETRY';
  nextAttemptAt = new Date(Date.now() + backoff(attemptCount)).toISOString();
}

return [{
  json: {
    id: replay.id,
    nextStatus,
    nextAttemptCount: attemptCount,
    nextAttemptAt,
    dlqReason,
    statusCode,
    idempotency_key: replay.idempotency_key,
    endpoint: replay.endpoint,
    first_failed_at: replay.first_failed_at,
    action: replay.action,
  },
}];

// Tail of the iteration — loop SplitInBatches back around. No
// per-iteration data shape needed; the SplitInBatches node manages
// continuation off its `done` output.
return items;
